    function LyricsBox() {
      useStore();
      const boxRef = useRef(null);
      const lines = store.lyrics ? store.lyrics.lines : [];
      let current = -1;
      for (let i = 0; i < lines.length; i++) {
        if (lines[i].t <= store.time) current = i;
        else break;
      }
      useEffect(() => {
        const box = boxRef.current;
        if (!box || current < 0) return;
        const active = box.querySelector(".nm-lyric-on");
        if (active) active.scrollIntoView({ block: "center", behavior: "smooth" });
      }, [current]);
      if (!lines.length) return null;
      const from = Math.max(0, current - 3);
      const slice = lines.slice(from, current + 4);
      return el(
        "div",
        { className: "nm-lyrics", ref: boxRef },
        slice.map((line, i) => el("div", { key: from + i, className: "nm-lyric" + (from + i === current ? " nm-lyric-on" : "") }, line.text || "…"))
      );
    }

